from collections import deque
from dataclasses import replace

from .model import Work


class ReviewScheduler:
    """Single inference-slot scheduler for foreground turns and memory reviews.

    One slot, one active work. Foreground always wins over a review that has not
    started yet, and a new foreground supersedes the review in flight:

    * a review of the *same* conversation is retired, it never runs again;
    * a review of another conversation is only interrupted - exactly one copy is
      kept and resumes once the slot goes idle;
    * a callback (late completion or late transport error) from a retired review
      or from a superseded attempt is rejected, so it cannot touch the current
      active work, cannot enter the completion history and cannot queue a retry;
    * a foreground that is already running is never preempted by another
      foreground - the new turn queues instead;
    * one foreground source triggers at most one review, and a review can never
      trigger a review, so the background work cannot recurse.

    ``transport.TransportAdapter`` only reports; the scheduler is the single
    retry owner. Retries keep the operation_id and ``attempt`` counts total
    attempts, bounded by ``max_attempts``.
    """

    def __init__(self, max_attempts=3):
        self.max_attempts = max_attempts
        self.foreground = deque()
        self.background = deque()
        self.active = None
        self.completed = []
        self._reviewed_sources = set()
        self._reviews_by_source = {}
        self._epoch = {}

    # ---------------- incarnation bookkeeping ----------------

    def _reopen(self, operation_id):
        """Start the next incarnation of ``operation_id``; return its epoch."""
        epoch = self._epoch.get(operation_id, 0) + 1
        self._epoch[operation_id] = epoch
        return epoch

    def _stale(self, work):
        """True for an object that is no longer the current incarnation."""
        return work is None or work.epoch != self._epoch.get(work.operation_id, 0)

    def _queue_for(self, work):
        return self.background if work.kind == "review" else self.foreground

    def _enqueue(self, work):
        self._queue_for(work).append(work)
        return work

    # ---------------- submission ----------------

    def submit_foreground(self, conversation_id, operation_id):
        work = Work(operation_id, conversation_id, "foreground", epoch=self._reopen(operation_id))
        self._enqueue(work)
        # Background thinking must never delay a user turn.
        self._supersede_reviews(conversation_id)
        return work

    def trigger_review(self, source):
        if source is None or source.kind != "foreground":
            return None                       # a review never triggers a review
        already = self._reviews_by_source.get(source.operation_id)
        if already is not None:
            return already                    # at most one review per source
        review_id = f"review:{source.operation_id}"
        review = Work(review_id, source.conversation_id, "review",
                      source_operation_id=source.operation_id, epoch=self._reopen(review_id))
        self._reviews_by_source[source.operation_id] = review
        self._reviewed_sources.add(source.operation_id)
        self._enqueue(review)
        return review

    def _supersede_reviews(self, conversation_id):
        active = self.active
        if active is not None and active.kind == "review" and not self._stale(active):
            self.active = None
            if active.conversation_id == conversation_id:
                self._reopen(active.operation_id)      # obsolete: it never runs again
            else:
                # interrupted, not cancelled: one copy resumes when the slot frees
                self._enqueue(replace(active, epoch=self._reopen(active.operation_id)))
        kept = []
        for queued in list(self.background):
            if queued.conversation_id == conversation_id:
                self._reopen(queued.operation_id)      # that conversation moved on
                continue
            kept.append(queued)
        self.background = deque(kept)

    # ---------------- the single slot ----------------

    def next_work(self):
        if self.active is not None:
            if not self._stale(self.active):
                return None                    # slot is busy, foregrounds queue up
            self.active = None
        for queue in (self.foreground, self.background):   # foreground first
            while queue:
                work = queue.popleft()
                if self._stale(work):
                    continue
                self.active = work
                return work
        return None

    def complete(self, work):
        if self._stale(work) or work is not self.active:
            return False            # late or foreign: current active stays untouched
        self.active = None
        if work.operation_id in self.completed:
            return False            # one operation is never recorded twice
        self.completed.append(work.operation_id)
        return True

    def transport_error(self, work):
        if self._stale(work) or work is not self.active:
            return False        # a retired review's error must not enqueue a retry
        self.active = None
        if work.attempt >= self.max_attempts:
            self._reopen(work.operation_id)         # total attempt budget is spent
            return False
        self._enqueue(replace(work, attempt=work.attempt + 1,
                              epoch=self._reopen(work.operation_id)))
        return True

