class TransportAdapter:
    """Reports a broken stream; the scheduler is the only retry owner.

    Used to requeue on top of the scheduler's own requeue: one dropped stream
    became two queued copies of the same operation, which doubled every attempt,
    blew past max_attempts and could record the same operation twice.
    """

    def __init__(self, scheduler):
        self.scheduler = scheduler

    def incomplete_stream(self, work):
        # Hand the failure over exactly once; the scheduler keeps the
        # operation_id, counts the attempt and decides whether the budget is spent.
        return self.scheduler.transport_error(work)
